import{_ as e,C as i,c as a,o,j as l,G as r,b as t,a0 as n,a as s,w as c,a1 as p}from"./chunks/framework.DKRgXLPU.js";const u=JSON.parse('{"title":"Gestione della pressione","description":"","frontmatter":{},"headers":[],"relativePath":"it/education/mental-strength/handling-pressure.md","filePath":"it/education/mental-strength/handling-pressure.md"}');const d=e({name:"it/education/mental-strength/handling-pressure.md"},[["render",function(e,u,d,m,h,g){const b=i("AdBanner"),q=i("Mermaid"),f=i("AdInArticle");return o(),a("div",null,[u[1]||(u[1]=l("h1",{id:"gestione-della-pressione",tabindex:"-1"},[s("Gestione della pressione "),l("a",{class:"header-anchor",href:"#gestione-della-pressione","aria-label":'Permalink to "Gestione della pressione"'},"​")],-1)),r(b),u[2]||(u[2]=l("p",null,"La pressione fa parte della competizione. L'obiettivo non è eliminarla, è impossibile. L'obiettivo è ottenere buoni risultati nonostante la pressione, e persino sfruttarla a proprio vantaggio.",-1)),u[3]||(u[3]=l("div",{class:"tip custom-block"},[l("p",{class:"custom-block-title"},"La grande idea"),l("p",null,[l("strong",null,"La pressione non scompare con l'esperienza: con essa si diventa più bravi a giocare."),s(" I giocatori migliori non sono calmi; sono abili nell'usare la loro eccitazione in modo produttivo.")])],-1)),(o(),t(p,null,{default:c(()=>[r(q,{id:"mermaid-13",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20A%5BSituazione%20di%20pressione%5D%20--%3E%20B%7BYour%20Response%7D%0A%20%20%20%20B%20--%3E%7CAnxiety%7C%20C%5BCalo%20delle%20prestazioni%5D%0A%20%20%20%20B%20--%3E%7CExcitement%7C%20D%5BAumento%20delle%20prestazioni%5D%0A%0A%20%20%20%20C%20--%3E%20E%5BPensieri%20negativi%5D%0A%20%20%20%20C%20--%3E%20F%5BTensione%5D%0A%20%20%20%20C%20--%3E%20G%5Bscarsa%20concentrazione%5D%0A%0A%20%20%20%20D%20--%3E%20H%5Benergizzato%5D%0A%20%20%20%20D%20--%3E%20I%5BConcentrato%5D%0A%20%20%20%20D%20--%3E%20J%5BFiducioso%5D%0A%0A%20%20%20%20style%20A%20fill%3A%23fff4e1%0A%20%20%20%20style%20B%20fill%3A%23e3f2fd%0A%20%20%20%20style%20C%20fill%3A%23ffebee%0A%20%20%20%20style%20D%20fill%3A%23e8f5e9%0A"})]),fallback:c(()=>[...u[0]||(u[0]=[s(" Loading... ",-1)])]),_:1})),u[4]||(u[4]=n('<h2 id="capire-la-pressione" tabindex="-1">Capire la pressione <a class="header-anchor" href="#capire-la-pressione" aria-label="Permalink to &quot;Capire la pressione&quot;">​</a></h2><h3 id="cosa-crea-pressione" tabindex="-1">Cosa crea pressione? <a class="header-anchor" href="#cosa-crea-pressione" aria-label="Permalink to &quot;Cosa crea pressione?&quot;">​</a></h3><ul><li>Alta posta in gioco (partita importante, tiro decisivo)</li><li>Essere osservati (pubblico, compagni di squadra)</li><li>Aspettative (tue e degli altri)</li><li>Incertezza (punteggio ravvicinato, avversari sconosciuti)</li><li>Tempo (che sta per scadere, che sta aspettando troppo a lungo)</li></ul><h3 id="cosa-fa-la-pressione-al-tuo-corpo" tabindex="-1">Cosa fa la pressione al tuo corpo <a class="header-anchor" href="#cosa-fa-la-pressione-al-tuo-corpo" aria-label="Permalink to &quot;Cosa fa la pressione al tuo corpo&quot;">​</a></h3><p>Quando senti pressione, il tuo corpo reagisce:</p><ul><li>La frequenza cardiaca aumenta</li><li>La respirazione diventa superficiale</li><li>Muscoli tesi</li><li>Le mani possono tremare</li><li>La messa a fuoco si restringe (a volte troppo)</li></ul><p>Questo è il tuo corpo che si prepara all&#39;azione. Non è male: è energia che puoi usare.</p><h2 id="pressione-di-riformulazione" tabindex="-1">Pressione di riformulazione <a class="header-anchor" href="#pressione-di-riformulazione" aria-label="Permalink to &quot;Pressione di riformulazione&quot;">​</a></h2><h3 id="pressione-come-eccitazione" tabindex="-1">Pressione come eccitazione <a class="header-anchor" href="#pressione-come-eccitazione" aria-label="Permalink to &quot;Pressione come eccitazione&quot;">​</a></h3><p>Le sensazioni fisiche di ansia ed eccitazione sono pressoché identiche. La differenza sta nel modo in cui le interpretiamo.</p><p><strong>Interpretazione dell&#39;ansia:</strong> &quot;Sono nervoso, potrebbe succedere qualcosa di brutto&quot; <strong>Interpretazione dell&#39;eccitazione:</strong> &quot;Sono energico, questo è importante per me&quot;</p><p><strong>Prova questo:</strong> Quando ti senti sotto pressione, di&#39; a te stesso: &quot;Sono emozionato&quot; invece di &quot;Sono nervoso&quot;.</p><h3 id="la-pressione-come-privilegio" tabindex="-1">La pressione come privilegio <a class="header-anchor" href="#la-pressione-come-privilegio" aria-label="Permalink to &quot;La pressione come privilegio&quot;">​</a></h3><p>Solo i momenti importanti creano pressione. Se la senti, sei in una situazione che conta.</p><blockquote><p>&quot;La pressione è un privilegio: capita solo a chi se la merita.&quot; - Billie Jean King</p></blockquote><h2 id="tecniche-per-momenti-di-alta-pressione" tabindex="-1">Tecniche per momenti di alta pressione <a class="header-anchor" href="#tecniche-per-momenti-di-alta-pressione" aria-label="Permalink to &quot;Tecniche per momenti di alta pressione&quot;">​</a></h2><h3 id="_1-controllo-del-respiro" tabindex="-1">1. Controllo del respiro <a class="header-anchor" href="#_1-controllo-del-respiro" aria-label="Permalink to &quot;1. Controllo del respiro&quot;">​</a></h3><p>Il respiro è il modo più veloce per cambiare il tuo stato.</p><p><strong>La tecnica 4-7-8:</strong></p><ol><li>Inspira per 4 conteggi</li><li>Mantieni la posizione per 7 conteggi</li><li>Espira per 8 conteggi</li><li>Ripetere 2-3 volte</li></ol><p><strong>Ripristino rapido (nel cerchio):</strong></p><ul><li>Un respiro lento e profondo</li><li>Senti i tuoi piedi per terra</li><li>Abbassa le spalle durante l&#39;espirazione</li></ul>',22)),r(f),u[5]||(u[5]=n('<h3 id="_2-radicamento-fisico" tabindex="-1">2. Radicamento fisico <a class="header-anchor" href="#_2-radicamento-fisico" aria-label="Permalink to &quot;2. Radicamento fisico&quot;">​</a></h3><p>Connettiti con le sensazioni fisiche per uscire dalla tua testa:</p><ul><li>Senti il peso della boccia</li><li>Nota i tuoi piedi a terra</li><li>Stringi e rilascia la mano che non lancia</li><li>Ruota le spalle indietro</li></ul><h3 id="_3-restringimento-della-messa-a-fuoco" tabindex="-1">3. Restringimento della messa a fuoco <a class="header-anchor" href="#_3-restringimento-della-messa-a-fuoco" aria-label="Permalink to &quot;3. Restringimento della messa a fuoco&quot;">​</a></h3><p>Nei momenti di pressione, concentrati solo su ciò che conta:</p><ul><li>Non il punteggio</li><li>Non il pubblico</li><li>Non quello che potrebbe succedere</li><li>Solo questo lancio, questo bersaglio, questo momento</li></ul><p><strong>Parole chiave:</strong> &quot;Qui. Ora. Questo.&quot;</p><h3 id="_4-focus-sul-processo" tabindex="-1">4. Focus sul processo <a class="header-anchor" href="#_4-focus-sul-processo" aria-label="Permalink to &quot;4. Focus sul processo&quot;">​</a></h3><p>Passare dal risultato al processo:</p><p><strong>Focalizzazione sul risultato (crea pressione):</strong></p><ul><li>&quot;Devo farlo&quot;</li><li>&quot;Se sbaglio, perdiamo&quot;</li><li>&quot;Tutti stanno guardando&quot;</li></ul><p><strong>Focus sul processo (riduce la pressione):</strong></p><ul><li>&quot;Segui la mia routine&quot;</li><li>&quot;Vedi il bersaglio&quot;</li><li>&quot;Fidati del mio allenamento&quot;</li></ul><h3 id="_5-la-stretta-della-mano-sinistra" tabindex="-1">5. La stretta della mano sinistra <a class="header-anchor" href="#_5-la-stretta-della-mano-sinistra" aria-label="Permalink to &quot;5. La stretta della mano sinistra&quot;">​</a></h3><p>Per i giocatori destrimani, stringere la mano sinistra per 10-15 secondi:</p><ul><li>Attiva l&#39;emisfero destro del cervello</li><li>Calma il pensiero analitico eccessivo</li><li>Aiuta ad accedere all&#39;esecuzione automatica</li></ul><p>Usalo quando ti accorgi di pensare troppo.</p><h2 id="preparazione-alla-pressione" tabindex="-1">Preparazione alla pressione <a class="header-anchor" href="#preparazione-alla-pressione" aria-label="Permalink to &quot;Preparazione alla pressione&quot;">​</a></h2><h3 id="simulare-la-pressione-nella-pratica" tabindex="-1">Simulare la pressione nella pratica <a class="header-anchor" href="#simulare-la-pressione-nella-pratica" aria-label="Permalink to &quot;Simulare la pressione nella pratica&quot;">​</a></h3><p>Non puoi gestire la pressione della competizione se non la provi mai durante l&#39;allenamento.</p><p><strong>Modi per creare pressione durante la pratica:</strong></p><ul><li>Stabilisci delle conseguenze (flessioni per chi sbaglia, offri un caffè al partner)</li><li>Creare scenari &quot;da non perdere&quot;</li><li>Esercitati con un pubblico</li><li>Pressione del tempo (timer)</li><li>Stanchezza (esercitare quando si è stanchi)</li></ul><h3 id="visualizzazione" tabindex="-1">Visualizzazione <a class="header-anchor" href="#visualizzazione" aria-label="Permalink to &quot;Visualizzazione&quot;">​</a></h3><p>Prova mentalmente le situazioni di forte pressione:</p><ol><li>Chiudi gli occhi</li><li>Immagina uno scenario di pressione in dettaglio</li><li>Senti le sensazioni di pressione</li><li>Immaginati mentre lo gestisci bene</li><li>Esegui con successo nella tua mente</li></ol><p>Fatelo regolarmente, non solo prima delle gare.</p><h3 id="costruisci-una-cronologia-della-pressione" tabindex="-1">Costruisci una cronologia della pressione <a class="header-anchor" href="#costruisci-una-cronologia-della-pressione" aria-label="Permalink to &quot;Costruisci una cronologia della pressione&quot;">​</a></h3><p>Tieni traccia delle volte in cui hai gestito bene la pressione:</p><ul><li>Qual era la situazione?</li><li>Come ti sei sentito?</li><li>Che cosa hai fatto?</li><li>Qual è stato il risultato?</li></ul><p>Rileggi questo prima delle gare per ricordarti: &quot;L&#39;ho già fatto prima&quot;.</p><h2 id="durante-la-competizione" tabindex="-1">Durante la competizione <a class="header-anchor" href="#durante-la-competizione" aria-label="Permalink to &quot;Durante la competizione&quot;">​</a></h2><h3 id="prima-del-lancio-di-pressione" tabindex="-1">Prima del lancio di pressione <a class="header-anchor" href="#prima-del-lancio-di-pressione" aria-label="Permalink to &quot;Prima del lancio di pressione&quot;">​</a></h3><ol><li>Fai un passo indietro, prendi fiato</li><li>Ricordati la tua routine</li><li>Concentrarsi sul processo, non sul risultato</li><li>Usa la tua parola chiave o il tuo segnale</li></ol><h3 id="nel-cerchio" tabindex="-1">Nel cerchio <a class="header-anchor" href="#nel-cerchio" aria-label="Permalink to &quot;Nel cerchio&quot;">​</a></h3><ol><li>Completa la tua routine esattamente come praticata</li><li>Concentrarsi esternamente (bersaglio, non corpo)</li><li>Fidati del tuo allenamento</li><li>Rilasciare senza esitazione</li></ol><h3 id="dopo-il-lancio" tabindex="-1">Dopo il lancio <a class="header-anchor" href="#dopo-il-lancio" aria-label="Permalink to &quot;Dopo il lancio&quot;">​</a></h3><ul><li>Accetta il risultato senza giudizio</li><li>Se va bene: breve riconoscimento, andare avanti</li><li>Se non valido: metodo SOAS, reimposta per il lancio successivo</li></ul><h2 id="errori-comuni-di-pressione" tabindex="-1">Errori comuni di pressione <a class="header-anchor" href="#errori-comuni-di-pressione" aria-label="Permalink to &quot;Errori comuni di pressione&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Errore</th><th>Approccio migliore</th></tr></thead><tbody><tr><td>correre</td><td>Rallenta, usa la routine completa</td></tr><tr><td>Troppi pensieri</td><td>Focus esterno, formazione sulla fiducia</td></tr><tr><td>Cambiare tecnica</td><td>Attieniti a ciò che conosci</td></tr><tr><td>Concentrarsi sul risultato</td><td>Concentrarsi sul processo</td></tr><tr><td>Combattere i nervi</td><td>Accetta e usa l&#39;energia</td></tr></tbody></table><h2 id="conclusione-chiave" tabindex="-1">Conclusione chiave <a class="header-anchor" href="#conclusione-chiave" aria-label="Permalink to &quot;Conclusione chiave&quot;">​</a></h2><blockquote><p>La pressione non scompare con l&#39;esperienza. Con essa si diventa più bravi a ottenere risultati migliori.</p></blockquote><p>I giocatori migliori non sono calmi: sono abili nell&#39;usare la loro eccitazione in modo produttivo.</p>',42)),r(b)])}]]);export{u as __pageData,d as default};
